import axios from "axios";
export default class FolderAPI {
    constructor() {
        this.cache = {};
    }
    async saveFolderColorOf(folderId, selectedColor) {
        const response = await axios.post('/apps/foldercolor/saveColor', {
            folderId: folderId,
            color: selectedColor
        });
        this.changeFolderColorInHtml(selectedColor, folderId);
        this.cache[folderId] = selectedColor;
    }
    async getFolderColorOf(folderId) {
        const response = await axios.get('/apps/foldercolor/getColor', {
            params: { folderId }
        });
        const color = response.data.color;
        this.cache[folderId] = color;
        if (color)
            this.changeFolderColorInHtml(color, folderId);
    }
    changeFolderColorInHtml(color, folderId) {
        const folderRow = document.querySelector(`tr[data-cy-files-list-row-fileid="${folderId}"]`);
        if (!folderRow)
            return;
        folderRow.dataset.foldercolor = color;
        folderRow.style.setProperty('--foldercolor', color);
    }
}
